        if (net_notice_t > 0) draw_text_c(H - 110.0f, net_notice, 2, GS_SETREG_RGBAQ(235, 130, 60, 0x80, 0));
        draw_text_c(H - 58.0f, "ARRIBA/ABAJO: ELEGIR   X: UNIRSE", 2, hint_c);
